#include <bits/stdc++.h>
using namespace std;
const int mod=998244353;

bool pref(int n,int i,int x,int s, int side){
    int need = (i-1)/2;
    if(side){
        int e=i+x-n-1;
        return max(s-1,e)==need;
    }
    if(i+x-n-1!=need)return false;
    return n+1-x+s<=i;
}
bool suff(int n, int i,int x,int s, int side){
    int p=n+1-i;
    int ns=x-s;
    int newside=1-side;
    return pref(n,p,x,ns,newside);
}
int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int t;
	cin>>t;
	while(t--){
	    int n;
	    cin>>n;
	    vector<int>a(n+1);
	    for(int i=1;i<=n;++i){
	        cin>>a[i];
	    }
	    if(n==1){
	        cout<<1<<endl;
	        continue;
	    }
	    bool mp=false;
	    for(int i=1;i<=n;i++){
	        if(a[i]==n && i!=1 && i!=n){
	            mp=true;
	            break;
	        }
	    }
	    bool fl=(a[1]==n);
	    bool fr=(a[n]==n);
	    
	    if(fl && fr)mp=true;
	    if(mp){
	        cout<<0<<endl;
	        continue;
	    }
	    vector<vector<unsigned char >> allow(n);
	    for(int x=1;x<n;++x){
	        allow[x].assign(x+1,3);
	        
	    }
	    for(int i=1;i<=n;++i){
	        int x=a[i];
	        if(x==n)continue;
	        auto & v=allow[x];
	        for(int s=0;s<=x;++s){
	            unsigned char m=v[s];
	            if(m & 1){
	                bool ok=pref(n,i,x,s,0) || suff(n,i,x,s,0);
	                if(!ok){
	                    m&= ~1;
	                }
	            }
	            if(m & 2){
	                bool ok=pref(n,i,x,s,1) || suff(n,i,x,s,1);
	                if(!ok)m&= ~2;
	            }
	            v[s]=m;
	        }
	    }
	    vector<int>dp(n,0),ndp(n,0);
	    dp[0]=1;
	    for(int x=1;x<n;++x){
	        fill(ndp.begin(),ndp.end(),0);
	        for(int s=0;s<x;++s){
	            int curr=dp[s];
	            if(curr==0)continue;
	            if(allow[x][s] & 1){
	                ndp[s]+=curr;
	                if(ndp[s]>=mod){
	                    ndp[s]-=mod;
	                }
	            }
	            if(allow[x][s+1] & 2){
	                ndp[s+1]+=curr;
	                if(ndp[s+1]>=mod)ndp[s+1]-=mod;
	            }
	        }
	        dp.swap(ndp);
	    }
	    int ans=0;
	    if(fl){
	        ans=dp[0];
	        
	    }
	    else if(fr){
	        ans=dp[n-1];
	    }
	    else {
	        for(int s=0;s<n;++s){
	            ans+=dp[s];
	            if(ans>=mod)ans-=mod;
	        }
	    }
	    cout<<ans<<endl;
	    
	}
	return 0;
	

}
